SELECT mr.message_id, c.id, c.link_id, c.email_address, COALESCE(mr.name, c.name) as "name", -- name from message overrides contact name c.original_photo_url, c.sfs_photo_url, c.created_at, c.updated_at, mr.recipient_type as "recipient_type!: db::address::EmailRecipientType" FROM email_message_recipients mr JOIN email_contacts c ON mr.contact_id = c.id WHERE mr.message_id = $1 ORDER BY mr.recipient_type
